insert into public.sq_iq_items(id,bank_version,band,domain,payload) values('iq-1-0-logic-0-0',1,0,'logic','{"id":"iq-1-0-logic-0-0","domain":"logic","prompt":"Barcha doiralar — ko‘k shakllar. Barcha ko‘k shakllar — belgilangan shakllar. Qaysi xulosa albatta kelib chiqadi?","visual":{"kind":"sets","labels":["X","Y","Z"],"legend":["doiralar","ko‘k shakllar","belgilangan shakllar"]},"options":["Barcha doiralar — belgilangan shakllar.","Barcha belgilangan shakllar — doiralar.","Hech bir doiralar — belgilangan shakllar emas.","Barcha belgilangan shakllar — ko‘k shakllar."],"answer":0,"explanation":"Birinchi to‘plam ikkinchisining, ikkinchisi uchinchisining ichida. Demak birinchisi uchinchiga kiradi; teskari yo‘nalish kafolatlanmaydi."}'::jsonb) on conflict(id) do nothing;
