insert into public.sq_iq_items(id,bank_version,band,domain,payload) values('iq-1-1-logic-2-0',1,1,'logic','{"id":"iq-1-1-logic-2-0","domain":"logic","prompt":"Bu vazifadagi barcha beshburchaklar ko‘k. P shakli ko‘k emas. P haqida nimani aniq aytish mumkin?","visual":{"kind":"text"},"options":["P — beshburchak.","P — ko‘k.","P haqida hech qanday xulosa yo‘q.","P — beshburchak emas."],"answer":3,"explanation":"Agar P beshburchak bo‘lganida ko‘k bo‘lishi kerak edi. Bu shart bajarilmaydi, shuning uchun P bu guruhga kirmaydi."}'::jsonb) on conflict(id) do nothing;
