insert into public.sq_iq_items(id,bank_version,band,domain,payload) values('iq-1-1-spatial-0-0',1,1,'spatial','{"id":"iq-1-1-spatial-0-0","domain":"spatial","prompt":"Shaklni markaz atrofida soat yo‘nalishida 90° buring. Qaysi natija mos?","visual":{"kind":"gridShape","points":[[2,0],[1,0],[0,0],[0,1],[0,2]]},"options":[[[2,0],[1,0],[0,0],[0,1],[0,2]],[[2,2],[2,1],[2,0],[1,0],[0,0]],[[0,2],[1,2],[2,2],[2,1],[2,0]],[[0,0],[0,1],[0,2],[1,2],[2,2]]],"answer":1,"explanation":"Kataklar markaz atrofida 90° buriladi. Shaklning kataklari soni va bir-biriga ulanishi saqlanadi."}'::jsonb) on conflict(id) do nothing;
